SELECT FROM course_homework
ORDER BY ${params.orderBy}
ORDER BY create_time DESC

SELECT 
FROM course_homework ch
LEFT JOIN course c ON ch.course_id = c.id
LEFT JOIN user u ON ch.create_user = u.id


        AND ch.id = #{params.id}


        AND ch.course_id = #{params.courseId}


        AND ch.title LIKE CONCAT('%', #{params.title}, '%')


        AND ch.status = #{params.status}


        AND ch.create_user = #{params.createUser}


        AND c.title LIKE CONCAT('%', #{params.courseName}, '%')


        AND u.username LIKE CONCAT('%', #{params.teacherName}, '%')


ORDER BY ch.create_time DESC

